     return data ? JSON.parse(data) as TaskRegistryEntry : null
   }

-  async list(limit = 50): Promise<TaskRegistryEntry[]> {
-    const ids = await this.redis.zrevrange(this.INDEX_KEY, 0, limit - 1)
+  async list(opts?: { limit?: number; offset?: number; status?: TaskRegistryEntry["status"] }): Promise<TaskRegistryEntry[]> {
+    const limit = opts?.limit ?? 20
+    const offset = opts?.offset ?? 0
+    const ids = await this.redis.zrevrange(this.INDEX_KEY, offset, offset + limit - 1)
     const entries: TaskRegistryEntry[] = []
     for (const id of ids) {
       const entry = await this.get(id)
-      if (entry) entries.push(entry)
+      if (!entry) continue
+      if (opts?.status && entry.status !== opts.status) continue
+      entries.push(entry)
     }
     return entries
   }

+  async count(status?: TaskRegistryEntry["status"]): Promise<number> {
+    // Count recent up to 10k for safety; zcard gives total score count but we need optionally filter by status
+    if (!status) {
+      return this.redis.zcard(this.INDEX_KEY)
+    }
+    const ids = await this.redis.zrevrange(this.INDEX_KEY, 0, -1)
+    let c = 0
+    for (const id of ids) {
+      const e = await this.get(id)
+      if (e && e.status === status) c++
+    }
+    return c
+  }
+
+  async search(query: string, opts?: { limit?: number }): Promise<TaskRegistryEntry[]> {
+    const q = query.trim().toLowerCase()
+    const limit = Math.min(opts?.limit ?? 20, 50)
+    if (!q) return []
+    const ids = await this.redis.zrevrange(this.INDEX_KEY, 0, 199)
+    const out: TaskRegistryEntry[] = []
+    for (const id of ids) {
+      if (out.length >= limit) break
+      const e = await this.get(id)
+      if (!e) continue
+      const title = (e.issueTitle ?? "").toLowerCase()
+      const url = (e.issueUrl ?? "").toLowerCase()
+      if (title.includes(q) || url.includes(q)) out.push(e)
+    }
+    return out
+  }
+
+  async aggregateStats(): Promise<{ total: number; queued: number; running: number; done: number; failed: number; totalCostUsd: number }> {
+    const ids = await this.redis.zrevrange(this.INDEX_KEY, 0, 199)
+    let total = 0
+    let queued = 0
+    let running = 0
+    let done = 0
+    let failed = 0
+    let totalCostUsd = 0
+    for (const id of ids) {
+      const e = await this.get(id)
+      if (!e) continue
+      total++
+      if (e.status === 'queued') queued++
+      else if (e.status === 'running') running++
+      else if (e.status === 'done') done++
+      else if (e.status === 'failed') failed++
+      const m = await this.getMetrics(id)
+      if (m && typeof m.costUsd === 'number') totalCostUsd += m.costUsd
+    }
+    return { total, queued, running, done, failed, totalCostUsd }
+  }
+
   async saveMetrics(taskId: string, metrics: TaskMetricsSnapshot): Promise<void> {
     await this.redis.set(this.metricsKey(taskId), JSON.stringify(metrics), "EX", this.TTL)
   }
